// The fixtures under testdata/golden freeze what the generator emits today
// (#1516). They are written once and never regenerated by a flag: a generator
// change that moves a byte must edit the fixture by hand, in review.

func goldenProfile(langs ...string) WorkspaceProfile {
	return WorkspaceProfile{Languages: langs, Confidence: ConfidenceHigh, Source: SourceDeterministic}
}

// assertGolden compares every emitted path with testdata/golden/<prefix>.<base>
// and fails on a fixture with no emitted path, so a dropped file is caught too.
func assertGolden(t *testing.T, prefix string, got map[string]string) {
	t.Helper()
	want, err := filepath.Glob(filepath.Join("testdata", "golden", prefix+".*"))
	if err != nil {
		t.Fatal(err)
	}
	if len(want) != len(got) {
		t.Errorf("%s: %d fixtures, %d emitted paths %v", prefix, len(want), len(got), slices.Sorted(maps.Keys(got)))
	}
	for p, content := range got {
		fixture := filepath.Join("testdata", "golden", prefix+"."+path.Base(p))
		b, err := os.ReadFile(fixture)
		if err != nil {
			t.Errorf("%s: no fixture for emitted path %s: %v", prefix, p, err)
			continue
		}
		if string(b) != content {
			t.Errorf("%s: %s differs from %s\n--- got ---\n%s\n--- want ---\n%s", prefix, p, fixture, content, b)
		}
	}
}

// pinFileStatements is what the generated build's claude-code RUN appends to the
// golden Dockerfile; the export (EmitEnvAsCode) never carries it.
const pinFileStatements = "; \\\n    mkdir -p /usr/local/share/wardyn/inputs; \\\n" +
	"    printf '%s %s %s\\n' \"$ver\" \"$plat\" \"$sum\" > /usr/local/share/wardyn/inputs/claude-code\n"

func TestGenerateDevcontainer_ZeroPinsIsTheGoldenPlusThePinFile(t *testing.T) {
	for name, langs := range map[string][]string{
		"none":  nil,
		"go":    {"Go"},
		"multi": {"Go", "JavaScript", "Python"},
	} {
		t.Run(name, func(t *testing.T) {
			files, err := GenerateDevcontainer(goldenProfile(langs...), Pins{})
			if err != nil {
				t.Fatal(err)
			}
			df := files[genDockerfilePath]
			if strings.Count(df, "mkdir -p /usr/local/share/wardyn/inputs") != 1 || !strings.HasSuffix(df, pinFileStatements) {
				t.Fatalf("the claude-code RUN must end with exactly the pin-file statements:\n%s", df)
			}
			files[genDockerfilePath] = strings.TrimSuffix(df, pinFileStatements) + "\n"
			assertGolden(t, name, files)
		})
	}
}

func TestEmitEnvAsCode_Golden(t *testing.T) {
	files, err := EmitEnvAsCode(goldenProfile("Go", "JavaScript", "Python"), nil, "")
	if err != nil {
		t.Fatal(err)
	}
	assertGolden(t, "envascode-multi", files)
}

// goldenGoCacheKey is CacheKey() of the go golden profile under cacheKeySalt
// "v2"; a change here means every cached generated image rebuilds.
const goldenGoCacheKey = "6be87536aa2a4dd1c371015a0434878e0efef083c354d04b7a2855f252f4b617"

func TestCacheKey_Golden(t *testing.T) {
	if got := goldenProfile("Go").CacheKey(); got != goldenGoCacheKey {
		t.Fatalf("CacheKey() = %s, want %s", got, goldenGoCacheKey)
	}
}

func TestGeneratedInputs_MatchesGeneratedFiles(t *testing.T) {
	p := goldenProfile("Python", "Go", "JavaScript")
	in, err := GeneratedInputs(p, Pins{})
	if err != nil {
		t.Fatal(err)
	}
	files, err := GenerateDevcontainer(p, Pins{})
	if err != nil {
		t.Fatal(err)
	}
	if len(in.Generator.FilesSHA256) != len(files) {
		t.Fatalf("hashed %d files, generator emits %d", len(in.Generator.FilesSHA256), len(files))
	}
	for path, content := range files {
		sum := sha256.Sum256([]byte(content))
		if got := in.Generator.FilesSHA256[path]; got != hex.EncodeToString(sum[:]) {
			t.Errorf("%s: hash %q, want %x", path, got, sum)
		}
	}
	if in.Generator.Salt != cacheKeySalt || in.Base.Ref != genBaseImage || in.Base.Digest != "" {
		t.Errorf("base/salt = %+v / %q", in.Base, in.Generator.Salt)
	}
	wantRefs := slices.Sorted(maps.Keys(featuresFor(p.Languages)))
	var gotRefs []string
	for _, f := range in.Features {
		gotRefs = append(gotRefs, f.Ref)
		if f.Digest != "" || len(f.Options) != 0 {
			t.Errorf("feature %s: digest %q options %v, want empty", f.Ref, f.Digest, f.Options)
		}
	}
	if !slices.Equal(gotRefs, wantRefs) {
		t.Errorf("features %v, want %v", gotRefs, wantRefs)
	}
	if len(in.Installers) != 1 || in.Installers[0].Tool != "claude-code" || in.Installers[0].Channel != "stable" {
		t.Errorf("installers = %+v, want claude-code/stable", in.Installers)
	}
}
